"""Reuse source-reviewed reference verdicts only for exact K copies already read in context."""
import argparse,datetime,hashlib,json
from pathlib import Path
from frozen_schema_subset_v2 import validate,unique_object
P=Path(__file__).resolve().parent
parser=argparse.ArgumentParser();parser.add_argument('--task',choices=['cobra','zod'],required=True);args=parser.parse_args();task=args.task
protocol=json.loads((P/'verified-fact-render-protocol-v1.json').read_text());folder=P/'verified-fact-render-v1'/task/'K';raw=(folder/'model-content.txt').read_bytes();c=json.loads(raw,object_pairs_hook=unique_object);errors=validate(c,json.loads((folder/'request.json').read_text())['format']);assert not errors
refs={r['claim_id']:r for r in json.loads((P/'atomic-reference-ledger-v2.json').read_text())['claims']};ids=protocol['metadata'][task]['required_ids'];assert set(c['facts'])==set(ids);claims=[]
for cid in ids:
    ref=refs[cid];pair=c['facts'][cid];assert pair==ref['expected_interpretation'],'Not an exact copy; requires new manual semantic judgment, not automatic repair: '+cid
    source=P/'frozen-public-sources'/task/ref['source_path'];assert hashlib.sha256(source.read_bytes()).hexdigest()==ref['source_file_sha256'];assert ref['reference_verdict']=='SUPPORTED'
    claims.append({'claim_id':'K-'+task+'-'+cid,'reference_id':cid,'source_revision':ref['source_revision'],'source_path':ref['source_path'],'source_file_sha256':ref['source_file_sha256'],'source_lines':ref['source_lines'],'exact_source_evidence':ref['exact_source_evidence'],'expected_interpretation':ref['expected_interpretation'],'generated_interpretation':pair,'verdict':'SUPPORTED','critical_if_false':True,'bilingual_consistency':True,'reviewer':'Same campaign agent; actual output and pinned source context read. Support inherited from exact source-reviewed fact, not citation membership or arbitrary prose matching.','provenance':'Verbatim supplied bilingual reference copy; no autonomous fact discovery or new paraphrase.'})
review={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'task':task,'method':'K','content_sha256':hashlib.sha256(raw).hexdigest(),'schema_subset_errors':errors,'claims':claims,'all_generated_claims_reviewed':True,'all_required_claims_covered':True,'bilingual_semantics_correct':True,'critical_unsupported_claims':0,'source_only_semantic_admission':True,'required_ids_correct':ids,'unique_required_factual_precision':{'numerator':len(ids),'denominator':len(ids)},'coverage':{'numerator':len(ids),'denominator':len(ids)},'verbatim_supplied_reference_fact_pairs':len(ids),'additional_neural_factual_claims':0,'frozen_metadata_review':'Both source-only scope/exception/unknown/test/example/owner limits read with the actual language strings. FAQ reuses only the generated exact correct fact at predeclared ID; no added neural FAQ assertion. Final assembled-note dimension review is separate.','not_general_model_accuracy':True,'owner_approved':False,'training_gold':False,'optimizer_updates':0}
with (folder/'semantic-review-v1.json').open('x') as f:json.dump(review,f,indent=2,ensure_ascii=False);f.write('\n')
print(json.dumps({'task':task,'verbatim_correct_bilingual_fact_pairs':len(ids),'gate_eligible':True,'not_model_knowledge_gain':True},indent=2))
